description:
Write `public static class Describe` with `public static string Of(object obj)` using reflection. It returns the type's name followed by its public instance properties in alphabetical order, as `Name { A = 1, B = x }`. A property whose value is `null` is shown as `null`. An object with no public properties gives `Name { }`.

```csharp
Describe.Of(new Point(3, 4));                 // Point { X = 3, Y = 4 }
Describe.Of(new Person { Name = "Ada" });     // Person { Age = 0, Email = null, Name = Ada }
```

starter.Solution.cs:
public static class Describe
{
    public static string Of(object obj) => obj.ToString() ?? "";
}

solution.Solution.cs:
using System.Reflection;

public static class Describe
{
    public static string Of(object obj)
    {
        var type = obj.GetType();
        var parts = type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(p => p.GetIndexParameters().Length == 0)
            .OrderBy(p => p.Name, StringComparer.Ordinal)
            .Select(p => $"{p.Name} = {p.GetValue(obj) ?? "null"}");
        string inside = string.Join(", ", parts);
        return inside.Length == 0 ? $"{type.Name} {{ }}" : $"{type.Name} {{ {inside} }}";
    }
}

unitTests:
Test("records and classes", () =>
{
    CheckEq(Describe.Of(new Point(3, 4)), "Point { X = 3, Y = 4 }");
    CheckEq(Describe.Of(new Person { Name = "Ada" }), "Person { Age = 0, Email = null, Name = Ada }");
    CheckEq(Describe.Of(new Empty()), "Empty { }");
});

